INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.414, 62, 1, 1, 1, 0, 190801, "2025/01/31 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5, 1000001, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.099, 62, 2, 1, 1, 0, 190801, "2025/01/31 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5, 1000002, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 2.801, 63, 3, 1, 1, 0, 190801, "2025/01/31 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5, 1000003, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 0, 63, 4, 2, 1, 0, 190801, "2025/01/31 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", -416.5, 1000004, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 2.12, 64, 5, 2, 1, 0, 190801, "2025/01/31 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363, 1000005, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 1.68, 64, 6, 1, 1, 0, 190801, "2025/01/31 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363, 1000006, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 2.33, 64, 7, 2, 1, 0, 190801, "2025/01/31 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363, 1000007, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 7, 5.18, 61, 101, 3, 10201, -6, 133701, "2025/01/31 12:00:00", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", -285, 1020101, "ラビリスタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 8.77, 61, 201, 1, 10201, -2, 133901, "2025/01/31 12:00:00", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", -285, 1020102, "クリスティーナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 15.5, 61, 301, 6, 10201, 0, 133801, "2025/01/31 12:00:00", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", -285, 1020103, "ネネカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 5, 9.061, 61, 101, 2, 10202, 0, 134301, "2025/02/28 12:00:00", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", -285, 1020201, "ランファ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 7.699, 61, 201, 1, 10202, 0, 134401, "2025/02/28 12:00:00", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", -285, 1020202, "チカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 8.595, 61, 101, 1, 10203, 0, 134601, "2025/03/31 12:00:00", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", -285, 1020301, "アオイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 7.758, 61, 201, 1, 10203, 0, 134501, "2025/03/31 12:00:00", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", -285, 1020302, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 6, 7, 61, 101, 2, 10204, 0, 132302, "2025/04/30 12:00:00", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", -285, 1020401, "ルイズマリー");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 7.904, 61, 201, 1, 10204, 0, 132402, "2025/04/30 12:00:00", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", -285, 1020402, "イロハ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 8.487, 61, 301, 4, 10204, 0, 132502, "2025/04/30 12:00:00", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", -285, 1020403, "ソノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 8.763, 61, 101, 1, 10205, 0, 134901, "2025/05/31 12:00:00", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", -285, 1020502, "カノン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 6.417, 61, 201, 1, 10205, 0, 134801, "2025/05/31 12:00:00", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", -285, 1020503, "ツムギ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 7, 10.335, 61, 101, 3, 10206, 0, 135001, "2025/06/30 12:00:00", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", -285, 1020601, "エリス");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 4, 6.281, 61, 201, 2, 10206, 0, 135101, "2025/06/30 12:00:00", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", -285, 1020602, "シェフィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 12.244, 61, 301, 1, 10206, 0, 135201, "2025/06/30 12:00:00", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", -285, 1020603, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 8, 6.339, 61, 101, 2, 10207, 0, 135301, "2025/07/31 12:00:00", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", -285, 1020701, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 9, 8.184, 61, 201, 7, 10207, 0, 135401, "2025/07/31 12:00:00", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", -285, 1020702, "アネモネ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.906, 61, 101, 9, 10208, 0, 129101, "2025/08/31 12:00:00", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", -285, 1020801, "アイラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 14.465, 61, 201, 1, 10208, 0, 129201, "2025/08/31 12:00:00", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", -285, 1020802, "シナツ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.662, 61, 301, 4, 10208, 0, 100101, "2025/08/31 12:00:00", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", -285, 1020803, "ヒヨリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 10.915, 61, 401, 1, 10208, 0, 100301, "2025/08/31 12:00:00", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", -285, 1020804, "レイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 7, 6.042, 61, 101, 1, 10209, 0, 135802, "2025/09/30 12:00:00", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", -285, 1020901, "ユキノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 9.402, 61, 201, 4, 10209, 0, 135903, "2025/09/30 12:00:00", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", -285, 1020902, "サツキ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.16, 61, 301, 8, 10209, 0, 136902, "2025/09/30 12:00:00", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", -285, 1020903, "ルルィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 5, 61, 101, 3, 10210, 0, 137401, "2025/10/31 12:00:00", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", -285, 1021001, "カスミ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.12, 61, 201, 4, 10210, 0, 136001, "2025/10/31 12:00:00", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", -285, 1021002, "アラクネ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 6.386, 61, 301, 4, 10210, 0, 136202, "2025/10/31 12:00:00", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", -285, 1021003, "ナーナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 4, 7.438, 61, 101, 3, 10211, 0, 136402, "2025/11/30 12:00:00", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", -285, 1021101, "ユイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 5, 8.35, 61, 201, 1, 10211, 0, 136302, "2025/11/30 12:00:00", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", -285, 1021102, "ミソラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 5, 61, 101, 1, 10212, 0, 136501, "2025/12/31 12:00:00", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", -285, 1021201, "シズル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 5.25, 61, 201, 1, 10212, 0, 137902, "2025/12/31 12:00:00", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", -285, 1021202, "リノ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 7.5, 61, 301, 1, 10212, 0, 106801, "2025/12/31 12:00:00", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", -285, 1021203, "ラビリスタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 8.204, 61, 101, 1, 10213, 0, 126501, "2026/01/31 12:00:00", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", -285, 1021301, "ライラエル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 7.176, 61, 201, 1, 10213, 0, 129701, "2026/01/31 12:00:00", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", -285, 1021302, "ネフィ＝ネラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 5, 8.602, 61, 301, 1, 10213, 0, 133101, "2026/01/31 12:00:00", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", -285, 1021303, "ヴァイオレット");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 10.14, 61, 102, 1, 10213, 0, 138101, "2026/02/06 12:00:00", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", -285, 1021304, "ライラエル");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 7, 10.152, 61, 202, 1, 10213, 0, 138201, "2026/02/06 12:00:00", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", -285, 1021305, "ネフィ＝ネラ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 9.688, 61, 302, 4, 10213, 0, 138001, "2026/02/06 12:00:00", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", -285, 1021306, "ヴァイオレット");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 5.928, 61, 401, 2, 10213, 0, 138301, "2026/02/12 12:00:00", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", -285, 1021307, "ペコリーヌ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 9.19, 61, 101, 4, 10214, 0, 138702, "2026/02/28 12:00:00", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", -285, 1021401, "ワカナ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.724, 61, 201, 1, 10214, 0, 138802, "2026/02/28 12:00:00", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", -285, 1021402, "シオリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 7.758, 61, 101, 4, 10215, 0, 138902, "2026/03/31 12:00:00", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", -285, 1021501, "グレイス");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 4, 6.375, 61, 201, 6, 10215, 0, 139002, "2026/03/31 12:00:00", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", -285, 1021502, "キョウカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 6.173, 61, 301, 6, 10215, 0, 136902, "2026/03/31 12:00:00", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", -285, 1021503, "ルルィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 4.202, 61, 101, 6, 10216, 0, 139202, "2026/04/30 12:00:00", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", -285, 1021601, "ミホ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 2.842, 61, 201, 6, 10216, 0, 139302, "2026/04/30 12:00:00", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", -285, 1021602, "マホ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 4.598, 61, 301, 4, 10216, 0, 139402, "2026/04/30 12:00:00", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", -285, 1021603, "エリカ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 6.533, 61, 101, 4, 10217, 0, 125802, "2026/05/31 12:00:00", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", -285, 1021701, "リリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 5, 61, 301, 3, 10217, 0, 126102, "2026/05/31 12:00:00", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", -285, 1021702, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 4, 5.214, 61, 201, 3, 10217, 0, 126002, "2026/05/31 12:00:00", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", -285, 1021703, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.781, 61, 102, 1, 10217, 0, 139501, "2026/05/31 12:00:00", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", -285, 1021704, "リリ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 6.529, 61, 202, 2, 10217, 0, 139601, "2026/05/31 12:00:00", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", -285, 1021705, "クリア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.195, 61, 302, 3, 10217, 0, 139701, "2026/05/31 12:00:00", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", -285, 1021706, "プレシア");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 12.43, 61, 101, 2, 10218, 0, 139902, "2026/06/30 12:00:00", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", -285, 1021801, "ルイズマリー");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 6.35, 61, 201, 2, 10218, 0, 140001, "2026/06/30 12:00:00", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", -285, 1021802, "クレジッタ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 5, 10.23, 61, 101, 1, 10219, 0, 140102, "2026/07/31 12:00:00", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", -285, 1021901, "フブキ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 5.584, 61, 201, 1, 10219, 0, 140201, "2026/07/31 12:00:00", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", -285, 1021902, "ヴァンピィ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 2.8, 61, 201, 6, 10220, 0, 126401, "2026/08/31 12:00:00", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", -285, 1022001, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.9, 61, 101, 4, 10220, 0, 127802, "2026/08/31 12:00:00", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", -285, 1022002, "ヴルム");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 4.49, 61, 202, 2, 10220, 0, 140602, "2026/08/31 12:00:00", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", -285, 1022003, "クローチェ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 9.42, 61, 102, 1, 10220, 0, 140501, "2026/08/31 12:00:00", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", -285, 1022004, "ヴルム");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 7, 61, 301, 4, 10220, 0, 140402, "2026/08/31 12:00:00", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", -285, 1022005, "リーザ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.61, 61, 101, 1, 10221, 0, 141101, "2026/10/31 12:00:00", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", -285, 1022101, "アーモンドアイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 3.55, 61, 201, 6, 10221, 0, 141201, "2026/10/31 12:00:00", "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", -285, 1022102, "ラッキーライラック");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.26, 61, 301, 2, 10221, 0, 141301, "2026/10/31 12:00:00", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", -285, 1022103, "デアリングタクト");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.79, 61, 401, 2, 10221, 0, 141001, "2026/10/31 12:00:00", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", -285, 1022104, "ゴールドシップ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 3, 8.61, 61, 101, 1, 10221, 0, 141101, "2026/10/31 12:00:00", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", -285, 1022105, "アーモンドアイ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 2.69, 61, 202, 1, 10221, 0, 141201, "2026/10/31 12:00:00", "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", -285, 1022106, "ラッキーライラック");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.26, 61, 301, 2, 10221, 0, 141301, "2026/10/31 12:00:00", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", -285, 1022107, "デアリングタクト");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 8.79, 61, 401, 2, 10221, 0, 141001, "2026/10/31 12:00:00", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", -285, 1022108, "ゴールドシップ");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.414, 62, 1, 1, 2, 0, 190805, "2026/04/10 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5, 2000001, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 3.099, 62, 2, 1, 2, 0, 190805, "2026/04/10 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5, 2000002, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 2.801, 63, 3, 1, 2, 0, 190805, "2026/04/10 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5, 2000003, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 0, 63, 4, 2, 2, 0, 190805, "2026/04/10 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", -416.5, 2000004, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 2.12, 64, 5, 2, 2, 0, 190805, "2026/04/10 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363, 2000005, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 2, 1.68, 64, 6, 1, 2, 0, 190805, "2026/04/10 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363, 2000006, "カリン");
INSERT INTO `v1_ec9a5cee5b2d79422c14537557cebe750643eeb1cd28a484957644dacc16de8d` VALUES ("2030/01/01 14:59:59", 1, 2.33, 64, 7, 2, 2, 0, 190805, "2026/04/10 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363, 2000007, "カリン");
